// A complete arcade time attack: stable camera, traffic, drift, nitro and checkpoints.
export default function createDrive(api){
  const W=960,H=600,LENGTH=6000,VIEW=2100;
  const routes=[{name:'Coastal Afterglow',sky:['#282d49','#db8175','#f2ba91'],land:'#987b6b',road:'#4b4c55',curve:.34,type:0},{name:'Redrock Pass',sky:['#433043','#c4775e','#e7b67c'],land:'#bc8663',road:'#46454a',curve:.56,type:1},{name:'Midnight Express',sky:['#10172c','#383a64','#816880'],land:'#323443',road:'#353843',curve:.3,type:2}];
  let route,position,speed,lateral,steerVelocity,health,nitro,clock,timeLeft,coins,misses,driftPoints,combo,comboClock,traffic,pickups,particles,wave,nextSpawn,checkpoint,invincible,done,bump,notice,noticeTime,boosting,drifting,offroad;
  const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
  const held=(...names)=>names.some(n=>api.input.keys.has(n));
  const curveAt=z=>Math.min(1,z/500)*(Math.sin(z/(route.type===1?390:670))*route.curve+Math.sin(z/1500)*.16);
  function project(z,lane=0){const scale=360/(Math.max(0,z)+360),horizon=203+Math.sin(position/850)*7;return{x:480+curveAt(position+z*.65)*210*(1-scale)**1.5+(lane-lateral)*350*scale,y:horizon+(600-horizon)*scale,half:436*scale,s:scale};}
  function message(t){notice=t;noticeTime=2.5;api.setHint(t);}
  function hud(){api.hud({Route:route.name,Distance:`${(position/1000).toFixed(1)} / 6 km`,Speed:`${Math.round(speed)} km/h`,Integrity:`${Math.max(0,Math.ceil(health))}%`,Nitro:`${Math.round(nitro)}%`,Time:`${Math.ceil(timeLeft)}s`,Score:Math.floor(position+coins*120+misses*160+driftPoints)});}
  function reset(){route=routes[clamp(Number(api.options?.route)||0,0,2)];position=0;speed=0;lateral=0;steerVelocity=0;health=100;nitro=75;clock=0;timeLeft=55;coins=misses=driftPoints=combo=comboClock=wave=checkpoint=invincible=bump=0;nextSpawn=180;traffic=[];pickups=[];particles=[];done=false;boosting=drifting=offroad=false;spawn();nextSpawn=180;notice='Reach each 2 km checkpoint for +40 seconds.';noticeTime=4;api.setHint('Steer with ← → / A D. ↑ / W uses nitro, ↓ / S brakes. Hold Space while steering to drift. Checkpoints add time.');hud();}
  function finish(won){if(done)return;done=true;const score=Math.floor(position+coins*120+misses*160+driftPoints+(won?health*35+Math.max(0,timeLeft)*20:0));hud();api.end(score,won?'Finish line crossed':health<=0?'Car retired':'Time is up',won?`${route.name} · ${clock.toFixed(1)}s · ${coins} tokens · ${misses} near misses · ${Math.ceil(health)}% integrity.`:`${(position/1000).toFixed(1)} km completed. Brake for traffic, save nitro for open road, and counter-steer through bends.`);api.sound(won?'win':'hit');}
  function spawn(){const lanes=[-.68,0,.68],lane=(wave*7+Math.floor(wave/4))%3,type=wave%5===3?'barrier':'car';traffic.push({z:position+690+(wave%3)*65,lane:lanes[lane],speed:type==='barrier'?0:45+(wave%4)*18,type,color:['#8db9bd','#d3b776','#a89ac7','#c68b7d'][wave%4],passed:false});const free=lanes[(lane+1+(wave%2))%3];for(let i=0;i<4;i++)pickups.push({z:position+520+i*42,lane:free,taken:false,passed:false});wave++;nextSpawn+=180+(wave%3)*35;}
  function update(dt){if(done)return;clock+=dt;timeLeft-=dt;noticeTime=Math.max(0,noticeTime-dt);invincible=Math.max(0,invincible-dt);bump=Math.max(0,bump-dt*3);
    const steering=Number(held('ArrowRight','d','D'))-Number(held('ArrowLeft','a','A')),brake=held('ArrowDown','s','S');offroad=Math.abs(lateral)>1.12;drifting=held('Space',' ')&&steering!==0&&speed>110&&!offroad;boosting=held('ArrowUp','w','W')&&nitro>1&&!brake&&!offroad;
    const target=offroad?150:brake?145:boosting?660:drifting?390:450;speed+=(target-speed)*Math.min(1,dt*(brake?5.5:boosting?3:2.5));
    nitro=clamp(nitro+(boosting?-22:4)*dt,0,100);const response=drifting?6:12;steerVelocity+=(steering*(drifting?1.8:1.45)-steerVelocity)*Math.min(1,dt*response);lateral+=steerVelocity*dt-curveAt(position)*dt*(speed/460)*.32;lateral=clamp(lateral,-1.65,1.65);
    if(offroad){health-=dt*7;combo=0;}if(drifting){comboClock+=dt;combo=Math.min(5,1+Math.floor(comboClock/1.5));driftPoints+=dt*35*combo;}else if(comboClock>0){if(comboClock>.5)message(`Drift banked · ×${combo} combo`);comboClock=0;combo=0;}
    const before=position;position=Math.min(LENGTH,position+speed/3.6*dt);while(position>=nextSpawn&&nextSpawn<LENGTH-600)spawn();
    for(const ob of traffic){const oldZ=ob.z-before;ob.z+=ob.speed/3.6*dt;const z=ob.z-position;if(!ob.passed&&oldZ>64&&z<=64){ob.passed=true;const gap=Math.abs(lateral-ob.lane);if(gap<.26&&invincible<=0){health-=22;invincible=1.8;speed*=.45;bump=1;comboClock=combo=0;message('Collision · −22% integrity');api.sound('hit');}else if(gap<.48&&invincible<=0){misses++;nitro=clamp(nitro+12,0,100);message('Near miss · +160 · nitro restored');api.sound('tap');}}}
    for(const token of pickups){if(!token.passed&&token.z-before>58&&token.z-position<=58){token.passed=true;if(Math.abs(lateral-token.lane)<.29){token.taken=true;coins++;nitro=clamp(nitro+3,0,100);api.sound('tap');}}}
    traffic=traffic.filter(ob=>ob.z-position>-90);pickups=pickups.filter(p=>p.z-position>-90&&!p.taken);
    if(position>=(checkpoint+1)*2000&&checkpoint<2){checkpoint++;timeLeft+=40;health=Math.min(100,health+8);message(`Checkpoint ${checkpoint}/2 · +40s · repaired 8%`);api.sound('win');}
    if((drifting||offroad)&&Math.random()<dt*38)particles.push({x:480+(Math.random()-.5)*85,y:555,r:4,life:.6,color:offroad?'#cebc99':'#d4d0d9'});for(const p of particles){p.y+=dt*36;p.r+=dt*18;p.life-=dt;}particles=particles.filter(p=>p.life>0);
    if(Math.floor(clock*8)!==Math.floor((clock-dt)*8))hud();if(health<=0||timeLeft<=0)finish(false);else if(position>=LENGTH)finish(true);
  }
  function poly(c,ps,fill){c.fillStyle=fill;c.beginPath();ps.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fill();}
  function rr(c,x,y,w,h,r,color){c.fillStyle=color;c.beginPath();c.roundRect(x,y,w,h,r);c.fill();}
  function text(c,t,x,y,size,color,align='left'){c.textAlign=align;c.font=`${size}px Arial`;c.fillStyle=color;c.fillText(t,x,y);}
  function backdrop(c){const bg=c.createLinearGradient(0,0,0,290);route.sky.forEach((col,i)=>bg.addColorStop(i/2,col));c.fillStyle=bg;c.fillRect(0,0,W,H);if(route.type<2){c.fillStyle='#ffd3a2';c.beginPath();c.arc(735-Math.sin(position/800)*26,115,62,0,7);c.fill();}else{c.fillStyle='#d6c7dd';c.beginPath();c.arc(744,106,28,0,7);c.fill();for(let i=0;i<45;i++){c.fillStyle='#dbd4e785';c.fillRect((i*127)%960,35+(i*47)%150,1.5,1.5);}}
    if(route.type===0){c.fillStyle='#748a91';c.fillRect(0,194,960,200);for(let i=0;i<16;i++){c.strokeStyle='#e3c4a73d';c.beginPath();const y=208+i*i*.8;c.moveTo(0,y);c.lineTo(960,y);c.stroke();}poly(c,[[0,215],[100,176],[195,160],[282,199],[365,171],[473,214],[960,255],[960,600],[0,600]],'#8f7980');}
    if(route.type===1){poly(c,[[0,230],[0,105],[90,105],[113,160],[220,160],[258,113],[341,120],[369,193],[482,206],[555,139],[658,140],[695,190],[775,130],[890,136],[960,215],[960,600],[0,600]],'#a16d64');}
    if(route.type===2){for(let i=0;i<22;i++){const x=i*48-35-Math.sin(position/1200)*20,h=32+(i*79)%116;c.fillStyle=i%2?'#282b44':'#36334b';c.fillRect(x,220-h,41,h+90);for(let j=0;j<5;j++){c.fillStyle=j%2?'#dfac9255':'#8db8c755';c.fillRect(x+9+(j%2)*15,230-h+j*17,5,5);}}}
    c.fillStyle=route.land;c.fillRect(0,254,960,346);
  }
  function road(c){for(let i=87;i>=0;i--){const z=i*VIEW/88,a=project(z),b=project(z+VIEW/88),band=Math.floor((position+z)/18)%2;poly(c,[[b.x-b.half*1.12,b.y],[b.x+b.half*1.12,b.y],[a.x+a.half*1.12,a.y],[a.x-a.half*1.12,a.y]],route.type===0?'#918276':'#6d6665');poly(c,[[b.x-b.half*1.04,b.y],[b.x+b.half*1.04,b.y],[a.x+a.half*1.04,a.y],[a.x-a.half*1.04,a.y]],band?'#d5c5b0':'#aa7265');poly(c,[[b.x-b.half,b.y],[b.x+b.half,b.y],[a.x+a.half,a.y],[a.x-a.half,a.y]],band?route.road:'#41434b');if(Math.floor((position+z)/25)%3===0)for(const lane of[-1/3,1/3])poly(c,[[b.x+b.half*(lane-.004),b.y],[b.x+b.half*(lane+.004),b.y],[a.x+a.half*(lane+.004),a.y],[a.x+a.half*(lane-.004),a.y]],'#d7ccb8');
      for(const side of[-1,1])poly(c,[[b.x+side*b.half*1.075,b.y-15*b.s],[b.x+side*b.half*1.09,b.y-15*b.s],[a.x+side*a.half*1.09,a.y-15*a.s],[a.x+side*a.half*1.075,a.y-15*a.s]],route.type===2?'#94abb8':'#d6c9b4');}
    for(let z=120-position%150;z<VIEW;z+=150){const p=project(z);for(const side of[-1,1]){c.strokeStyle='#817a78';c.lineWidth=Math.max(1,4*p.s);c.beginPath();c.moveTo(p.x+side*p.half*1.1,p.y);c.lineTo(p.x+side*p.half*1.1,p.y-25*p.s);c.stroke();}}
  }
  function roadside(c){for(let z=VIEW-position%170;z>40;z-=170){const p=project(z),side=Math.floor((position+z)/170)%2?1:-1,x=p.x+side*p.half*1.4,s=p.s,y=p.y;if(route.type===0){c.strokeStyle='#665e57';c.lineWidth=6*s;c.beginPath();c.moveTo(x,y);c.quadraticCurveTo(x-12*s,y-65*s,x+4*s,y-112*s);c.stroke();c.strokeStyle='#52695d';c.lineWidth=7*s;for(let j=0;j<5;j++){const a=j*Math.PI/2.3;c.beginPath();c.moveTo(x+4*s,y-112*s);c.quadraticCurveTo(x+Math.cos(a)*35*s,y-145*s,x+Math.cos(a)*58*s,y-108*s+Math.sin(a)*24*s);c.stroke();}}else if(route.type===1){poly(c,[[x-24*s,y],[x-17*s,y-46*s],[x+5*s,y-67*s],[x+27*s,y-41*s],[x+34*s,y]],'#9e7363');poly(c,[[x+5*s,y-67*s],[x+27*s,y-41*s],[x+34*s,y],[x+8*s,y]],'#7c625d');}else{c.strokeStyle='#8c9da4';c.lineWidth=4*s;c.beginPath();c.moveTo(x,y);c.lineTo(x,y-150*s);c.lineTo(x-side*45*s,y-150*s);c.stroke();c.fillStyle='#ffdf99';c.beginPath();c.ellipse(x-side*45*s,y-146*s,9*s,3*s,0,0,7);c.fill();}}}
  function car(c,x,y,s,color,angle=0,player=false){c.save();c.translate(x,y);c.scale(s,s);c.rotate(angle);c.fillStyle='#16192266';c.beginPath();c.ellipse(0,2,60,14,0,0,7);c.fill();rr(c,-51,-46,12,45,3,'#20242c');rr(c,39,-46,12,45,3,'#20242c');poly(c,[[-47,0],[-45,-34],[-29,-75],[29,-75],[45,-34],[47,0]],color);poly(c,[[-34,-31],[-24,-65],[24,-65],[34,-31]],'#1c2634');poly(c,[[-24,-61],[-27,-35],[2,-35],[17,-61]],'#718592');rr(c,-46,-21,92,24,5,color);c.fillStyle=player&&held('ArrowDown','s')?'#ff625b':'#f59e83';c.fillRect(-40,-13,23,6);c.fillRect(17,-13,23,6);c.fillStyle='#eae2c7';c.fillRect(-12,-9,24,6);c.fillStyle='#313340';c.fillRect(-52,-28,104,5);c.fillRect(-41,2,82,3);if(player&&boosting){poly(c,[[-21,5],[-10,5],[-15,25+Math.random()*20]],'#8cdeef');poly(c,[[10,5],[21,5],[15,25+Math.random()*20]],'#8cdeef');}c.restore();}
  function draw(c){c.save();if(bump)c.translate(Math.sin(clock*75)*bump*4,Math.cos(clock*61)*bump*2);backdrop(c);road(c);roadside(c);const things=[...traffic.map(o=>({...o,kind:o.type})),...pickups.filter(p=>!p.taken).map(p=>({...p,kind:'token'}))].filter(o=>o.z-position>-20&&o.z-position<VIEW).sort((a,b)=>b.z-a.z);for(const ob of things){const p=project(ob.z-position,ob.lane);if(ob.kind==='car')car(c,p.x,p.y,p.s*1.02,ob.color);else if(ob.kind==='barrier'){rr(c,p.x-52*p.s,p.y-42*p.s,104*p.s,35*p.s,3*p.s,'#dbc092');for(let i=0;i<5;i++)poly(c,[[p.x+(-48+i*20)*p.s,p.y-42*p.s],[p.x+(-38+i*20)*p.s,p.y-42*p.s],[p.x+(-21+i*20)*p.s,p.y-7*p.s],[p.x+(-31+i*20)*p.s,p.y-7*p.s]],'#4e4850');}else{c.fillStyle='#eec982';c.strokeStyle='#aa7950';c.lineWidth=3*p.s;c.beginPath();c.arc(p.x,p.y-24*p.s,14*p.s,0,7);c.fill();c.stroke();}}
    for(const p of particles){c.globalAlpha=p.life*.35;c.fillStyle=p.color;c.beginPath();c.arc(p.x,p.y,p.r,0,7);c.fill();}c.globalAlpha=invincible>0&&Math.floor(clock*12)%2?.45:1;car(c,480,555,1.12,'#e59f76',-steerVelocity*(drifting?.11:.035),true);c.globalAlpha=1;
    rr(c,25,23,244,60,6,'#1b2232d9');text(c,route.name.toUpperCase(),39,46,11,'#eadcc8');text(c,`${Math.round(speed)} km/h`,39,70,19,'#f7e9d7');rr(c,725,23,210,60,6,'#1b2232d9');text(c,`${Math.ceil(timeLeft)}s`,741,49,24,timeLeft<15?'#ffac95':'#f1dfbc');text(c,`CHECKPOINT ${checkpoint} / 2`,741,70,9,'#b5bfbd');
    rr(c,26,100,180,5,2,'#372f38');rr(c,26,100,180*Math.max(0,health)/100,5,2,health<35?'#eb8e7c':'#b9d79a');text(c,'INTEGRITY',26,121,8,'#ddd1c5');rr(c,25,564,186,5,2,'#292a3c');rr(c,25,564,186*nitro/100,5,2,'#96d8e5');text(c,'NITRO  ↑ / W',25,589,10,'#b6d3d8');text(c,`${(position/1000).toFixed(1)} / 6.0 km`,935,589,12,'#d6d1c5','right');
    if(noticeTime>0){rr(c,260,96,440,35,5,'#172233b8');text(c,notice,480,119,13,'#f3d8aa','center');}else if(offroad)text(c,'RETURN TO THE ROAD',480,111,15,'#ffd2ae','center');else if(drifting)text(c,`DRIFT ×${combo}`,480,112,20,'#f3c79b','center');
    c.restore();}
  return{reset,update,draw};
}


